// Records frames of the Plane Sight app while fake states play.
// usage: node rec.mjs <outdir> <scenario>
import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";

const out = process.argv[2];
const scenario = process.argv[3] ?? "park";
mkdirSync(out, { recursive: true });
const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const port = 9333;
const chrome = spawn(CHROME, [
  "--headless=new", `--remote-debugging-port=${port}`, `--user-data-dir=${out}/profile`,
  "--window-size=1280,720", "--hide-scrollbars", "--force-device-scale-factor=1", "--use-angle=swiftshader", "--enable-unsafe-swiftshader", "about:blank",
], { stdio: "ignore" });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let ws;
for (let i = 0; i < 50; i++) {
  try {
    const list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    const page = list.find((p) => p.type === "page");
    ws = new WebSocket(page.webSocketDebuggerUrl);
    await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; });
    break;
  } catch { await sleep(200); }
}
let id = 0;
const pending = new Map();
ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });

const fake = `
window.EventSource = class { constructor() { window.__es = this; } close() {} };
window.__push = (s) => window.__es.onmessage({ data: JSON.stringify(s) });
window.fetch = async () => new Response("ok");
`;
await send("Page.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
await send("Page.addScriptToEvaluateOnNewDocument", { source: fake });
await send("Page.navigate", { url: "http://localhost:5173/" });
await sleep(4000);

const plane = (n, status, need = null, tokens = 100000, agent = "claude") => ({
  session: `s${n}`, pane: null, agent, name: `agent-${n}`, title: `Task ${n}`, repo: "demo", status, tokens, files: [], need,
});
const need = (n, rank, skipped = false) => ({
  kind: "approval", key: `k${n}`, skipped, since: Date.now() - 60000, rank, reason: null, urgency: null, request: null,
  message: null, collision: null, card: { title: `Card ${n}`, summary: "x", category: "approval", proposal: { action: "allow", text: "ok" }, reasoning: "", effort_seconds: 5, risk: "low" }, cardPending: false,
});
const state = (planes) => ({ now: Date.now(), gemini: { enabled: false, lastError: null }, planes });
const push = (planes) => send("Runtime.evaluate", { expression: `window.__push(${JSON.stringify(state(planes))})` });

let frame = 0;
async function record(ms, every = 120) {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    const { result } = await send("Page.captureScreenshot", { format: "jpeg", quality: 70 });
    writeFileSync(`${out}/f${String(frame++).padStart(3, "0")}.jpg`, Buffer.from(result.data, "base64"));
    await sleep(every);
  }
}

const scenarios = {
  // three planes wait at holds, one flies, three are parked; then they swap places
  async park() {
    const a = [
      plane(1, "blocked", need(1, 0)), plane(2, "blocked", need(2, 1)), plane(3, "blocked", need(3, 2), 500000, "codex"),
      plane(4, "working", null), plane(5, "idle"), plane(6, "idle", null, 500000), plane(7, "idle", null, 100000, "codex"),
    ];
    await push(a);
    await record(4500, 300);
    // 1 is skipped (hold -> stand), 4 lands (flying -> stand), 5 needs you (stand -> queue)
    const b = [
      plane(1, "idle", need(1, 0, true)), plane(2, "blocked", need(2, 0)), plane(3, "blocked", need(3, 1), 500000, "codex"),
      plane(4, "idle", null), plane(5, "blocked", need(5, 2)), plane(6, "idle", null, 500000), plane(7, "idle", null, 100000, "codex"),
    ];
    await push(b);
    await record(6000);
  },
};
await scenarios[scenario]();
ws.close();
chrome.kill();
console.log(`${frame} frames in ${out}`);

